/**
 * Shader de la grille sinusoidale.
 *
 * ## L'idee mathematique
 *
 * Une grille n'est pas dessinee, elle est lue : la distance a la ligne la
 * plus proche est la partie fractionnaire des coordonnees, recentree. Pour
 * faire osciller chaque noeud, on ne deplace pas les noeuds — on deforme le
 * domaine avant de le lire. Un decalage en sinus de y sur x, et en sinus de x
 * sur y, avec le temps dans la phase : chaque noeud decrit une petite boucle,
 * et les lignes qui le joignent se courbent avec lui.
 *
 * Le moire vient d'une seconde grille, lue sur le meme domaine mais un peu
 * plus fine, tournee de quelques degres et deformee en contre-phase. La ou
 * les deux reseaux coincident, les traits s'additionnent ; la ou ils se
 * decalent, ils s'annulent a moitie. Les franges qui en resultent se
 * deplacent lentement — bien plus lentement que les noeuds — parce qu'elles
 * dependent de la difference des deux deformations, pas de leur somme.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — le fond.
 * - `uColorB` — les lignes.
 * - `uColorC` — les noeuds.
 * - `uCells` — nombre de cellules sur la hauteur.
 * - `uAmplitude` — course de l'oscillation, en cellules.
 * - `uSpeed` — vitesse de l'oscillation.
 * - `uMoire` — poids de la seconde grille.
 */
export const SINE_GRID_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uCells;
uniform float uAmplitude;
uniform float uSpeed;
uniform float uMoire;

// Distance a la ligne la plus proche d'une grille unitaire.
float grille(vec2 q) {
  vec2 local = abs(fract(q + 0.5) - 0.5);
  return min(local.x, local.y);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  float cells = clamp(uCells, 2.0, 40.0);
  vec2 p = vUv * vec2(aspect, 1.0) * cells;
  float t = uTime * uSpeed;

  // Un pixel, en unites de cellule.
  float px = cells / max(uResolution.y, 1.0);
  float amplitude = clamp(uAmplitude, 0.0, 0.5);

  // Le domaine est deforme avant lecture : chaque noeud decrit une boucle.
  vec2 q = p + amplitude * vec2(sin(p.y * 1.1 + t), sin(p.x * 0.9 - t * 1.3));

  float lines = 1.0 - smoothstep(px * 0.5, px * 1.5, grille(q));
  float node = 1.0 - smoothstep(px * 2.0, px * 3.5, length(fract(q + 0.5) - 0.5));

  // La seconde grille : un peu plus fine, tournee, deformee en contre-phase.
  float angle = 0.07;
  mat2 turn = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
  vec2 r = turn * p * 1.04;
  vec2 q2 = r + amplitude * vec2(sin(r.y * 1.1 - t), sin(r.x * 0.9 + t * 1.3));
  float lines2 = 1.0 - smoothstep(px * 0.5, px * 1.5, grille(q2));

  float ink = clamp(lines * 0.7 + lines2 * uMoire * 0.5, 0.0, 1.0);

  vec3 colour = mix(uColorA, uColorB, ink);
  colour = mix(colour, uColorC, node);

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Grille sinusoidale : une grille dont chaque noeud oscille, et un moire leger.
 *
 * ## Le principe
 *
 * Les noeuds ne sont pas deplaces : le domaine est deforme en sinus avant que
 * la grille y soit lue, et chaque noeud decrit une petite boucle avec les
 * lignes qui le joignent. Une seconde grille, un peu plus fine et tournee de
 * quelques degres, se superpose en contre-phase : ses franges de moire se
 * deplacent bien plus lentement que les noeuds.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur — les recopier ici en ferait autant
 * de versions a maintenir qu'il y a de fonds.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface — il n'en
 * accorde qu'une par backend — et sous mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { SINE_GRID_FRAGMENT } from './sine-grid.shader.js'

/** Ce que l'echappatoire recoit. */
export interface SineGridControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface SineGridOwnProps {
  /** Nombre de cellules sur la hauteur. Borne a quarante par le shader. @defaultValue 12 */
  cells?: number
  /** Course de l'oscillation, en cellules. @defaultValue 0.18 */
  amplitude?: number
  /** Vitesse de l'oscillation. @defaultValue 0.8 */
  speed?: number
  /** Poids de la seconde grille, celle du moire. Zero l'eteint. @defaultValue 0.6 */
  moire?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<SineGridControls>
}

/** Toutes les proprietes. */
export type SineGridProps = Customisable<SineGridOwnProps>

/** Tokens employes par defaut : le fond, les lignes, les noeuds. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-theme-line',
  '--o-palette-brand-500',
] as const

/** Repli par defaut : une teinte figee, dans les memes tons. */
const DEFAULT_FALLBACK = 'o-bg-zinc-50 dark:o-bg-zinc-950'

/**
 * Grille sinusoidale.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <SineGrid className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function SineGrid({
  cells = 12,
  amplitude = 0.18,
  speed = 0.8,
  moire = 0.6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: SineGridProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: SINE_GRID_FRAGMENT,
    colors,
    uniforms: { uCells: cells, uAmplitude: amplitude, uSpeed: speed, uMoire: moire },
    name: 'sine-grid',
    // La seconde grille double les lectures et, a densite de pixels reduite,
    // ses franges scintillent : en qualite basse elle s'eteint.
    degrade: (quality) => ({ uMoire: quality === 'low' ? 0 : moire }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
